// === Tab: mySketch ===
let Shader;
let cSlider,zSlider;
let cmult = 1.0;
let zmult = 1.0;

function preload() {
	Shader = getShader(this._renderer);
}

function setup() {
	createCanvas(1112, 834, WEBGL);

	cSlider= createSlider(0,1000,500);
	cSlider.position(40,20);  
	cSlider.input(sliderChange);

	zSlider= createSlider(0,1000,500);
	zSlider.position(40,60);  
	zSlider.input(sliderChange);
}

// ----------------------------------------------------

function sliderChange() {
	cmult = 0.95 + 0.2 * float(cSlider.value()) / 1000.0;
	zmult = 0.80 + 0.5 * float(zSlider.value()) / 1000.0;

	//console.log("cmult: " + cmult + ";  zmult: " + zmult);
}

// ----------------------------------------------------

function draw() {
	shader(Shader);

	let angle = frameCount * 0.001 + PI / 2;
	let change = 0.8;

	Shader.setUniform('c', [cos(angle) * change, sin(angle) * change]);
	Shader.setUniform('cmult',cmult);
	Shader.setUniform('zmult',zmult);
	rect(0, 0, width, height);
}

// save jpg
let lapse = 0;    // mouse timer
function mousePressed(){
  // prevents mouse press from registering twice
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
    lapse = millis();
  }
}

function getShader(_renderer) {
	const vert = `
		precision highp float;
		attribute vec3 aPosition;
		attribute vec2 aTexCoord;
		varying vec2 vTexCoord;
		void main() {
			vTexCoord=aTexCoord;
			vec4 positionVec4=vec4(aPosition,1.);
			positionVec4.xy=positionVec4.xy*2.-1.; 
			gl_Position=positionVec4;
		}
	`;

	const frag = `
		precision highp float;
		varying vec2 vTexCoord;
		uniform sampler2D pal;
		uniform vec2 c;
		uniform float cmult,zmult;
		const float zh=${windowHeight/windowWidth};
		float o2,orbit = 9999.0;

		void main() {
			vec2 cc = c;
			vec2 z=vec2(5.*vTexCoord.x-2.5,(5.*vTexCoord.y-2.5)*zh);
			int iter=1000;

			z *= 0.3;

			for(int i=0;i<300;i++) {
				float x=(z.x+z.y)*(z.x-z.y)+cc.x;
				float y=2.*z.y*z.x+cc.y;
				if((x*x+y*y)>4.) {iter=i;break;}
				z.x=x;
				z.y=y;

				o2 = length(z);
				if(o2 < orbit) orbit = o2;

				cc.x *= cmult;
				cc.y *= cmult;
				z *= zmult;
			}

			//gl_FragColor = texture2D(pal,vec2(iter==100?0.0: 0.1 + float(iter * iter) * orbit * orbit * 0.01, 1));
			float cr = 0.0;
			float cg = 0.0;
			float cb = 0.0;

			if(iter < 1000) {
				cr = float(iter * iter) * 0.01;
				cg = orbit * orbit * 3.0;
				cb = cg / cr;
			}

			// alter contrast -------------
			float contrast = 36.3;//1.92;
			cr = 0.5 + (cr - 0.5) * contrast;
			cg = 0.5 + (cg - 0.5) * contrast;
			cb = 0.5 + (cb - 0.5) * contrast;

			gl_FragColor = vec4(cr,cg,cb,1);
		}
	`;
	return createShader(vert, frag);
}

